{
  "technical_and_design_decisions": [
    "U1 (Capabilities Framework): Introduce capabilities config protobuf structures and evaluation logic split into Channel, Orderer, and Application capability maps in common/channelconfig and common/capabilities. Enforce binary crash behavior on encountering unsupported capabilities during channel parsing.",
    "U2 (Read-Your-Writes): Extend the chaincode stub to track local write operations within an in-memory transaction buffer during transaction execution, allowing GetTrxState calls to retrieve modified keys prior to block commitment.",
    "U3 (Add Org Video/Guide): Produce a presentation diagram detailing live channel re-configuration phases and record a clear step-by-step video demonstration of adding an org dynamically without channel downtime.",
    "U4 (CouchDB Query Performance): Design a test suite to measure response times and resource utilization of simple key-value vs index-backed CouchDB rich queries on Fabric state database.",
    "U5 (MSPConfig Interface): Refactor MSPConfig from concrete structs to an interface abstraction, decoupling programmatically built channel configuration blocks from the configtxgen CLI executable.",
    "U6 (Singleton Removal): Refactor global singleton instances in the chaincode handling subsystem into injected dependencies to improve test isolation and concurrency handling.",
    "U7 (Dynamic Test Yaml Generation): Enhance integration test harnesses ('World') to dynamically render core.yaml and orderer.yaml configurations based on test scenario parameters.",
    "U8 (Lifecycle Validation Parameters Interface): Implement validation info interfaces for the new lifecycle chaincode manager, including explicit endorsement policy handling for internal '+lifecycle' system chaincode."
  ],
  "assumptions": [
    "Development work will be executed sequentially by an experienced Hyperledger Fabric developer.",
    "Existing test environments, CI pipelines, and benchmarking tools are readily available for usage.",
    "All effort estimates are provided in person-workdays (1 workday = 8 working hours)."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Implement Capabilities Framework (U1)",
      "activity_description": "Define Channel, Orderer, and Application capabilities maps, implement capability checking interfaces in common/channelconfig/api.go and common/capabilities, and enforce fail-fast (crash) logic for unsupported capabilities.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Implement Read-Your-Writes (RYW) in Chaincode Stub (U2)",
      "activity_description": "Extend chaincode stub shim API to support GetTrxState and maintain local uncommitted transaction state during chaincode execution.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Produce Video & Tutorial for Dynamic Org Addition (U3)",
      "activity_description": "Create architectural diagram graphics, script, record, and edit a video demonstration showing dynamic organization onboarding without bringing down the network.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Benchmark & Evaluate CouchDB Query Performance (U4)",
      "activity_description": "Execute performance tests on CouchDB state database queries, analyze indexing impacts on query execution, and produce performance reports.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Refactor MSPConfig to Interface (U5)",
      "activity_description": "Extract MSPConfig into Go interfaces to enable dynamic programmatical generation of channel configuration blocks without depending on configtxgen.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Remove Chaincode Singletons (U6)",
      "activity_description": "Refactor chaincode package code to eliminate global singletons in favor of dependency injection, improving unit testing and lifecycle flexibility.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Dynamic YAML Generation for Test Framework (U7)",
      "activity_description": "Update integration test framework to generate custom core.yaml and orderer.yaml files dynamically based on World context variables.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Implement Lifecycle Validation Parameters Interface (U8)",
      "activity_description": "Implement validation parameter retrieval interface for chaincodes within the new lifecycle, including built-in majority endorsement policy for '+lifecycle'.",
      "most_likely_effort": 5
    }
  ],
  "reported_total": {
    "most_likely_effort": 38
  }
}
